page.css:
:root { --ink: #1b1b1f; --muted: #5a5a66; --line: #d5d5dd; --paper: #ffffff; --wash: #f4f5f8; --accent: #1f4fd8; --accent-ink: #ffffff; --radius: 10px; --gap: 1rem; }
* { box-sizing: border-box; }
body { margin: 0px; font: 16px / 1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; color: var(--ink); background: var(--wash); }
body > header { background: var(--paper); border-bottom: 1px solid var(--line); }
body > header nav { max-width: 62rem; margin: 0px auto; padding: 0.75rem 1rem; display: flex; align-items: center; gap: var(--gap); }
body > header nav a { color: var(--ink); text-decoration: none; }
body > header nav a[aria-current="page"] { font-weight: 600; }
main { max-width: 62rem; margin: 0px auto; padding: 1.5rem 1rem; display: grid; gap: 1.5rem; grid-template-columns: 2fr 1fr; align-items: start; }
main > h1, main > p.lede { grid-column: 1 / -1; }
aside { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); padding: 1rem; }
footer { max-width: 62rem; margin: 0px auto; padding: 1rem; color: var(--muted); }
h1 { font-size: 1.9rem; margin: 0px; }
h2 { font-size: 1.2rem; margin: 0px 0px 0.5rem; }
.lede { color: var(--muted); margin: 0px; }
form { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); padding: 1rem; }
fieldset { border: 0px; padding: 0px; margin: 0px; display: grid; gap: 0.75rem; }
label { display: block; font-weight: 600; margin-bottom: 0.25rem; }
input, select, textarea { width: 100%; padding: 0.55rem 0.65rem; border: 1px solid var(--line); border-radius: 8px; font: inherit; background: var(--paper); }
input:focus-visible, select:focus-visible, textarea:focus-visible, button:focus-visible, a:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
button { background: var(--accent); color: var(--accent-ink); border: 0px; border-radius: 8px; padding: 0.65rem 1.1rem; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-weight: 600; cursor: pointer; }
.grid { display: grid; gap: var(--gap); grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr)); }
article { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); padding: 1rem; }
article h3 { margin: 0px 0px 0.25rem; font-size: 1rem; }
article p { margin: 0px 0px 0.5rem; color: var(--muted); }
.pagination { display: flex; gap: 0.5rem; list-style: none; padding: 0px; margin: 0px; }
.pagination a { display: inline-block; padding: 0.35rem 0.7rem; border: 1px solid var(--line); border-radius: 8px; text-decoration: none; color: var(--ink); background: var(--paper); }
.hint { color: var(--muted); font-size: 0.9rem; }
dl { display: grid; grid-template-columns: 10rem 1fr; gap: 0.35rem 0.75rem; margin: 0px; }
dt { font-weight: 600; }
dd { margin: 0px; color: var(--muted); }
@media (max-width: 44rem) {
  main { grid-template-columns: 1fr; }
}
